(()=>{function init(){const layers=[];for(const e of document.querySelectorAll('.modal,.first-run-flow,#feedback')){const d=document.createElement('dialog');d.className='ss-layer';d.id='layer-'+e.id;document.body.append(d);d.append(e);e.removeAttribute('role');e.removeAttribute('aria-modal');const label=e.id==='feedback'?'feedback-title':e.getAttribute('aria-labelledby');if(label)d.setAttribute('aria-labelledby',label);else d.setAttribute('aria-label',e.getAttribute('aria-label')||'訓練面板');if(e.id==='feedback'){d.setAttribute('aria-describedby','feedback-message');d.addEventListener('click',ev=>{if(ev.target.closest('.btn-next')){e.classList.add('hidden');d.close()}},true);d.addEventListener('keydown',ev=>{if(ev.key==='Enter'){ev.preventDefault();ev.stopImmediatePropagation();e.querySelector('.btn-next')?.click()}},true)}d.addEventListener('cancel',ev=>{ev.preventDefault();if(e.id==='feedback')e.querySelector('.btn-next')?.click();else{const b=e.querySelector('.btn-close');if(b)b.click();else e.classList.add('hidden')}});layers.push({e,d})}const nav=document.getElementById('app-bottom-nav'),host=document.querySelector('.train-app'),anchor=document.createElement('span');anchor.hidden=true;nav.before(anchor);const mq=matchMedia('(min-width:1100px)');function place(){if(mq.matches)host.insertBefore(nav,host.querySelector('.tab-panel')||host.firstChild);else anchor.before(nav)}mq.addEventListener('change',place);place();function sync(){for(const{e,d}of layers){if(!e.classList.contains('hidden')&&!d.open)d.showModal();else if(e.classList.contains('hidden')&&d.open)d.close()}document.querySelectorAll('.home-hub-card').forEach(e=>e.remove());document.querySelectorAll('[style]').forEach(e=>{if(e.tagName==='HTML'||e.closest('#hero-table'))return;const bg=e.style.background||e.style.backgroundColor;if(bg&&!bg.startsWith('var('))e.style.background='var(--soft)';if(e.style.color&&!e.style.color.startsWith('var('))e.style.color='var(--ink)'});const tab=document.body.dataset.activeTab||'plan';for(const e of nav.querySelectorAll('[data-app-tab]'))if(e.dataset.appTab===tab){if(e.getAttribute('aria-current')!=='page')e.setAttribute('aria-current','page')}else e.removeAttribute('aria-current')}sync();new MutationObserver(sync).observe(document.body,{subtree:true,childList:true,attributes:true,attributeFilter:['class']});runWrongAnswerCue=function(el){if(state.feedbackPreferences?.wrongAnswerFeedbackEnabled&&!matchMedia('(prefers-reduced-motion:reduce)').matches&&el?.animate)el.animate([{outlineColor:'#b78e88'},{outlineColor:'transparent'}],{duration:300})};const old=window.handleAction;window.handleAction=function(...a){try{return old(...a)}finally{sync()}}}document.addEventListener('DOMContentLoaded',init)})();
document.addEventListener('DOMContentLoaded',()=>{const m=new URLSearchParams(location.search).get('mode');if(['RFI','DEFEND','FACING_3BET','ALL_STREET','PUSH_FOLD','CUSTOM'].includes(m)){changeMode(m,true);setActiveTab('practice')}});
